from PIL import Image
import numpy as np
im=np.array(Image.open('mol_0331.png').convert('L'))<128
sub=im[295:355,470:600]
# label components
from collections import deque
lab=np.zeros(sub.shape,int); n=0
for i in range(sub.shape[0]):
  for j in range(sub.shape[1]):
    if sub[i,j] and lab[i,j]==0:
      n+=1; q=deque([(i,j)]); lab[i,j]=n
      while q:
        a,b=q.popleft()
        for da in(-1,0,1):
          for db in(-1,0,1):
            x,y=a+da,b+db
            if 0<=x<sub.shape[0] and 0<=y<sub.shape[1] and sub[x,y] and lab[x,y]==0:
              lab[x,y]=n; q.append((x,y))
for k in range(1,n+1):
  ys,xs=np.where(lab==k)
  print(k, 'x',xs.min()+470,xs.max()+470,'y',ys.min()+295,ys.max()+295,'size',len(xs))
"

